example_queries:
# Ten software records with a DOI, and their titles
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?record ?doi ?title WHERE {
  ?record a oaire:Software ; oaire:doi ?doi ; oaire:title ?title .
} LIMIT 10

# Open-access software records published in 2020
PREFIX oaire: <https://w3id.org/rete/openaire#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?record ?title WHERE {
  ?record oaire:publicationYear "2020"^^xsd:gYear ; oaire:accessRight "OPEN" ; oaire:title ?title .
} LIMIT 20

# Where to read them: full-text links
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?record ?url WHERE {
  ?record oaire:fulltextUrl ?url .
} LIMIT 20

# Records with their publisher and language
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?record ?publisher ?language WHERE {
  ?record oaire:publisherName ?publisher ; oaire:language ?language .
} LIMIT 20
